<template>
  <div class="pcb-scope pcb-result">
    <header class="pcb-head"><div><p class="pcb-eyebrow">PCB / 分割结果</p><div class="pcb-result-title"><h1>PCB 表面缺陷分割结果</h1><TaskStatus v-if="task" :status="task.status" /></div><p class="pcb-code">任务 {{ taskId }}</p></div><div class="pcb-actions"><router-link v-if="task?.parent_batch_id" :to="'/inspect/pcb/batches/' + encodeURIComponent(task.parent_batch_id)">返回批次对比</router-link><router-link to="/inspect/pcb">新建分割</router-link><router-link to="/records?type=pcb_segmentation">历史记录</router-link></div></header>
    <p class="pcb-muted pcb-cancel-notice">{{ PCB_CANCEL_NOTICE }}。原系统尚无统一取消协议；离开页面不会停止任务。“新建分割”会创建独立任务。</p>
    <div v-if="loading && !task" class="pcb-state" role="status">正在读取 PCB 分割结果…</div>
    <div v-if="loadError" class="pcb-state error" role="alert"><strong>PCB 结果暂不可用</strong><p>{{ loadError }}</p><el-button :loading="loading" @click="refresh">重新加载</el-button></div>
    <template v-if="task && !loadError">
      <div v-if="pending" class="pcb-state" role="status"><strong>{{ task.status === 'queued' ? '任务已排队' : '正在进行 CPU 分割' }}</strong><p>结果完成后自动更新。可以离开此页，稍后从历史记录继续查看。</p></div>
      <div v-if="task.error_summary || task.status === 'failed'" class="pcb-state error" role="alert"><strong>本次分割未完成</strong><p>{{ task.error_summary || '任务执行失败，请检查输入或联系管理员查看服务状态。' }}</p><router-link to="/inspect/pcb">检查输入并新建任务 →</router-link></div>
      <section class="pcb-panel pcb-result-panel">
        <div class="pcb-panel-head"><div><h2>{{ task.model?.name || '模型信息暂不可用' }}</h2><p>{{ task.samples[0]?.filename || '单张 PCB 图像' }} · {{ dimensions }} · {{ task.has_gt ? '已提供配对 GT' : '未提供 GT' }}</p></div><el-button v-if="task.result_download_url" :loading="downloading === 'json'" @click="downloadJSON">下载结果 JSON</el-button></div>
        <div v-if="task.status === 'success'" class="pcb-layer-toolbar" role="group" aria-label="结果图层"><button v-for="layer in layerOptions" :key="layer.kind" type="button" :disabled="!artifact(layer.kind)" :aria-pressed="selected === layer.kind" @click="selected = layer.kind">{{ layer.label }}</button></div>
        <p v-if="task.status === 'success' && !artifact('mask_visual') && artifact('pred_mask')" class="pcb-note pcb-mask-legacy">旧任务未生成可视化掩码（0/255）。请选择原始二值掩码（0/1）：页面提亮便于观察，下载仍保留原始 0/1 像素值。</p>
        <div class="pcb-viewers">
          <figure><figcaption><span>原始图像</span><span class="pcb-code">RGB · {{ dimensions }}</span></figcaption><div class="pcb-frame pcb-result-frame"><img v-if="artifact('origin') && !failedImages.origin" :src="artifact('origin')?.url" alt="PCB 原始图像" @error="failedImages.origin = true" /><span v-else class="pcb-muted">{{ pending ? '结果生成后显示原图' : '原图暂不可用' }}</span></div></figure>
          <figure><figcaption><span>{{ currentLabel }}</span><span class="pcb-code">原图坐标</span></figcaption><div class="pcb-frame pcb-result-frame"><img v-if="currentArtifact && !failedImages[selected]" :key="currentArtifact.url" :src="currentArtifact.url" :alt="`PCB ${currentLabel}`" :class="{ 'pcb-mask': ['pred_mask','gt'].includes(selected) }" @error="failedImages[selected] = true" /><span v-else class="pcb-muted">{{ pending ? '等待分割完成' : currentArtifact ? '图层加载失败，请重新加载任务' : '当前没有可用图层' }}</span></div></figure>
        </div>
        <div class="pcb-view-footer"><p class="pcb-muted layer-description">{{ layerDescription }}</p><div class="pcb-actions"><el-button :disabled="!currentArtifact || !!failedImages[selected]" @click="zoomOpen = true">放大查看</el-button><el-button :disabled="!currentArtifact" :loading="downloading === 'layer'" @click="downloadLayer">下载当前图层</el-button></div></div>
        <p v-if="selected === 'probability'" class="pcb-probability-scale"><span>缺陷概率 0</span><i aria-hidden="true" /><span>1</span></p>
        <p v-if="downloadError" class="pcb-error" role="alert">{{ downloadError }}</p>
      </section>
      <div class="pcb-result-bottom">
        <section v-if="task.has_gt && task.metrics?.available" class="pcb-panel pcb-metrics" aria-label="当前图像 GT 指标"><div class="pcb-panel-head"><div><h2>当前图像的配对评价</h2><p>仅根据用户提供的 GT 计算，不代表测试集或现场泛化精度。</p></div></div><dl class="pcb-metric-grid"><div v-for="item in metricItems" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ percent(item.value) }}</dd></div></dl><p class="pcb-muted">TP {{ task.metrics.tp ?? '—' }} · FP {{ task.metrics.fp ?? '—' }} · FN {{ task.metrics.fn ?? '—' }} · TN {{ task.metrics.tn ?? '—' }}（像素）</p><p class="pcb-muted">“—” 表示该指标无定义；误差图中绿色为 TP、红色为 FP、蓝色为 FN。</p></section>
        <section v-else class="pcb-panel pcb-no-metrics"><h2>图像评价</h2><p class="pcb-muted">{{ task.has_gt ? '指标尚不可用，需等待任务成功完成。' : '未提供配对 GT，无法计算真实性能指标。' }}</p><p class="pcb-muted">缺陷概率表示模型输出，不能作为 Dice、IoU 或正确率。</p></section>
        <section class="pcb-panel pcb-cam-state"><div class="pcb-panel-head"><div><h2>Grad-CAM 解释图层</h2><p>独立于分割概率图的模型关注区域</p></div></div><p class="pcb-muted">{{ camMessage }}</p><p v-if="task.cam?.layer" class="pcb-code">目标层 {{ task.cam.layer }}</p><el-button v-if="artifact('cam')" @click="selected = 'cam'">查看 Grad-CAM</el-button></section>
      </div>
      <details class="pcb-panel pcb-provenance"><summary>查看输入与模型标识</summary><dl><div><dt>场景 / 任务</dt><dd>PCB / segmentation</dd></div><div><dt>模型</dt><dd>{{ task.model?.id || '—' }}</dd></div><div><dt>输入 SHA-256</dt><dd class="pcb-code">{{ task.samples[0]?.sha256 || '—' }}</dd></div><div><dt>权重 SHA-256</dt><dd class="pcb-code">{{ task.model?.weight_sha256 || '—' }}</dd></div><div><dt>处理协议</dt><dd class="pcb-code">{{ task.model?.protocol_hash || '—' }}</dd></div></dl></details>
    </template>
    <el-dialog v-model="zoomOpen" :title="currentLabel" width="min(780px, 94vw)" destroy-on-close class="pcb-zoom-dialog"><img v-if="currentArtifact" :src="currentArtifact.url" :alt="`${currentLabel} 放大查看`" :class="{ 'pcb-mask': ['pred_mask','gt'].includes(selected) }" /><p class="pcb-muted">{{ dimensions }} 原图坐标；放大仅用于观察，不改变下载文件。</p></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from "vue";
import { useRoute } from "vue-router";
import TaskStatus from "../../components/TaskStatus.vue";
import { formatError, http } from "../../api/http";
import { downloadAuthFile, saveBlobFile } from "../../api/labels";
import { PCB_CANCEL_NOTICE, type PcbTask } from "./types";
import "./pcb.css";
const route = useRoute(), taskId = computed(() => String(route.params.taskId ?? ""));
const task = ref<PcbTask | null>(null), loading = ref(false), loadError = ref(""), downloadError = ref(""), downloading = ref(""), selected = ref("overlay"), zoomOpen = ref(false);
const failedImages = reactive<Record<string, boolean>>({});
let generation = 0, disposed = false, timer: ReturnType<typeof setTimeout> | undefined;
const dimensions = computed(() => { const sample=task.value?.samples[0], plan=task.value?.input_plan; return (sample?.width || plan?.width || 220) + " × " + (sample?.height || plan?.height || 220); });
const pending = computed(() => ["queued", "running"].includes(task.value?.status ?? ""));
const layerOptions = computed(() => [{kind:"overlay",label:"缺陷叠加"},{kind:"pred_mask",label:"原始二值掩码（0/1）"},{kind:"mask_visual",label:"可视化掩码（0/255）"},{kind:"boundary",label:"缺陷边界"},{kind:"probability",label:"缺陷概率"},{kind:"cam",label:"Grad-CAM"},...(task.value?.has_gt ? [{kind:"gt",label:"配对 GT"},{kind:"error",label:"TP / FP / FN"}] : [])]);
function artifact(kind: string) { return task.value?.artifacts?.find(a => a.kind === kind && a.url.startsWith(`/api/tasks/${encodeURIComponent(taskId.value)}/file/`) && !a.url.includes("..")); }
const currentArtifact = computed(() => artifact(selected.value));
const currentLabel = computed(() => layerOptions.value.find(l => l.kind === selected.value)?.label ?? "分割图层");
const layerDescriptions: Record<string,string> = {overlay:"红色表示预测缺陷区域，透明叠加保留原图纹理。",pred_mask:"原始二值掩码（0/1）：背景为 0、缺陷为 1，用于程序分析与指标复算。页面仅提亮预览，下载保留原始 0/1 像素值。",mask_visual:"可视化掩码（0/255）：背景为 0、缺陷为 255，可直接在图片工具中查看。前景位置与原始二值掩码完全一致，不用于指标计算。",boundary:"黄色标记预测缺陷的外边界。",probability:"Viridis 颜色由紫到黄表示缺陷概率从低到高，与 Grad-CAM 不同。",cam:"Grad-CAM 表示模型对预测缺陷的关注区域，不表示缺陷概率或精度。",gt:"用户上传的配对真值，预览提高亮度以便观察。",error:"绿色 TP / 红色 FP / 蓝色 FN；仅在合法配对 GT 存在时提供。"};
const layerDescription = computed(() => layerDescriptions[selected.value] ?? "图层与原图坐标对齐。");
const metricItems = computed(() => [{label:"Defect Dice",value:task.value?.metrics?.defect_dice},{label:"Defect IoU",value:task.value?.metrics?.iou},{label:"Precision",value:task.value?.metrics?.precision},{label:"Recall",value:task.value?.metrics?.recall}]);
function percent(value: number | null | undefined) { return typeof value === "number" && Number.isFinite(value) ? `${(value * 100).toFixed(2)}%` : "—"; }
const camMessage = computed(() => { const cam = task.value?.cam; const text:Record<string,string> = {not_requested:"本次未请求 Grad-CAM。可在新任务的附加分析选项中开启。",not_supported_for_size:"仅原生 220 × 220 RGB 图片支持 CAM，本项仍提供分割与概率图层。",pending:"任务完成后查看解释图层。",ok:"解释图层已生成，可切换到 Grad-CAM 查看。",unavailable:"预测前景为空，Grad-CAM 不可用。基础分割结果仍然有效。",failed:"Grad-CAM 生成失败，基础分割结果仍然有效。"}; return [text[cam?.status ?? ""] ?? "解释图层暂不可用。",cam?.reason].filter(Boolean).join(" "); });
function stopTimer() { if (timer) clearTimeout(timer); timer = undefined; }
async function refresh() { if (loading.value || disposed) return; stopTimer(); loading.value = true; loadError.value = ""; const current = generation; try { const {data} = await http.get<PcbTask>(`/tasks/${encodeURIComponent(taskId.value)}`); if (disposed || generation !== current) return; if (data.type !== "pcb_segmentation" || data.scene !== "pcb" || data.task_kind !== "segmentation") throw new Error("该任务不是 PCB 分割任务，请从结果记录打开对应详情。"); task.value = data; Object.keys(failedImages).forEach(k => delete failedImages[k]); if (pending.value) timer = setTimeout(() => void refresh(), 2500); } catch(err) { if (!disposed && generation === current) loadError.value = formatError(err); } finally { if (!disposed && generation === current) loading.value = false; } }
async function downloadJSON() { const id = taskId.value, url = task.value?.result_download_url, current = generation; if (url !== `/api/tasks/${encodeURIComponent(id)}/file/pcb.json` || downloading.value) return; downloading.value = "json"; downloadError.value = ""; try { const {data} = await http.get(url.replace(/^\/api/, "")); if (!disposed && current === generation) saveBlobFile(new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),`${id}_pcb.json`); } catch(err) { if (!disposed && current === generation) downloadError.value = formatError(err); } finally { if (!disposed && current === generation) downloading.value = ""; } }
async function downloadLayer() { const item = currentArtifact.value, current = generation; if (!item || downloading.value) return; downloading.value = "layer"; downloadError.value = ""; try { await downloadAuthFile(item.url.replace(/^\/api/, ""),`${taskId.value}_${selected.value}.png`); } catch(err) { if (!disposed && current === generation) downloadError.value = formatError(err); } finally { if (!disposed && current === generation) downloading.value = ""; } }
watch(taskId, () => { generation++; stopTimer(); task.value = null; loading.value = false; loadError.value = ""; downloadError.value = ""; downloading.value = ""; selected.value = "overlay"; zoomOpen.value = false; void refresh(); }, { immediate:true });
onBeforeUnmount(() => { disposed = true; generation++; stopTimer(); });
</script>

<style scoped>
