cursor:pointer; color:#315a89; font-size:15px; }.pcb-provenance dl { margin-bottom:0; }.pcb-provenance dl>div { display:grid; grid-template-columns:145px minmax(0,1fr); gap:15px; margin-top:12px; }.pcb-provenance dt { color:#526c88; font-size:14px; }.pcb-provenance dd { margin:0; color:#294967; }.pcb-zoom-dialog img { display:block; width:100%; max-height:65vh; object-fit:contain; image-rendering:pixelated; background:#edf2f7; }.pcb-zoom-dialog .pcb-muted { margin-bottom:0; }
@media(max-width:1050px) { .pcb-result-bottom { grid-template-columns:minmax(0,1fr); }.pcb-result-frame { min-height:240px; padding:14px; }.pcb-result-frame img { width:100%; height:auto; max-height:400px; } } @media(max-width:600px) { .pcb-viewers { grid-template-columns:minmax(0,1fr); gap:18px; }.pcb-metric-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:20px; }.pcb-provenance dl>div { grid-template-columns:minmax(0,1fr); gap:3px; }.pcb-head>.pcb-actions { margin-top:0; }.pcb-layer-toolbar button { padding:8px 10px; font-size:13px; } }
</style>
